import{_ as s,j as a,k as n,a5 as o}from"./chunks/framework.3Z9w-w8R.js";const h=JSON.parse('{"title":"Namespaces","description":"Namespaces are identifiers that mark content ownership and are helpful because they keep naming conflicts from happening.","frontmatter":{"title":"Namespaces","mentions":["SirLich","MedicalJewel105"],"description":"Namespaces are identifiers that mark content ownership and are helpful because they keep naming conflicts from happening."},"headers":[{"level":2,"title":"Picking a namespace","slug":"picking-a-namespace","link":"#picking-a-namespace","children":[]},{"level":2,"title":"Where to use namespaces?","slug":"where-to-use-namespaces","link":"#where-to-use-namespaces","children":[]},{"level":2,"title":"Where NOT to use namespaces.","slug":"where-not-to-use-namespaces","link":"#where-not-to-use-namespaces","children":[]}],"relativePath":"concepts/namespaces.md","filePath":"concepts/namespaces.md"}'),c={name:"concepts/namespaces.md"};function i(t,e,p,r,l,d){return n(),a("div",null,e[0]||(e[0]=[o('<p>Namespaces are identifiers that mark content ownership. You can think of them as folders. Namespaces are helpful because they keep naming conflicts from happening.</p><p>Namespaces in add-on creation can essentially be thought of as &quot;the part to the left of the colon&quot;. For example, <code class="shiki"><span>minecraft</span></code> is the namespace of <code class="shiki"><span>minecraft:zombie</span></code>. The general form is <code class="shiki"><span>namespace:name</span></code>.</p><p>As a concrete example of why namespaces are helpful, let&#39;s imagine you create a new Mob. You name it <code class="shiki"><span>minecraft:shark</span></code>, not aware that you should create your own namespace for custom content. Next year, Mojang decides to add sharks into the game! Now there is a naming conflict since there are two definitions of <code class="shiki"><span>minecraft:shark</span></code>. Your add-on will break.</p><p>If you had instead used <code class="shiki"><span>your_namespace:shark</span></code>, the naming conflict wouldn&#39;t have happened.</p><h2 id="picking-a-namespace" tabindex="-1">Picking a namespace <a class="header-anchor" href="#picking-a-namespace" aria-label="Permalink to &quot;Picking a namespace&quot;">​</a></h2><p>A suitable namespace is unique to you. Something like <code class="shiki"><span>mob</span></code> or <code class="shiki"><span>cars</span></code> or <code class="shiki"><span>content</span></code> or <code class="shiki"><span>custom</span></code> would be a <strong>bad</strong> namespace since another developer might come up with the same namespace as you.</p><p>A suitable namespace is short. You will be writing your namespace a <strong>LOT</strong>, so the shorter, the better. <code class="shiki"><span>george_carlin_the_comedian</span></code> would be a lousy namespace for this reason.</p><p>For personal projects, I recommend a convenient version of your player name, and for commercial projects, I recommend a suitable version of the company name.</p><p>Some good examples:</p><ul><li><code class="shiki"><span>gcarlin</span></code></li><li><code class="shiki"><span>sirlich</span></code></li><li><code class="shiki"><span>cubeworld</span></code></li><li><code class="shiki"><span>bworks</span></code></li></ul><p><strong>DO NOT USE</strong> <code class="shiki"><span>minecraft</span></code> or <code class="shiki"><span>minecon</span></code> as a namespace unless editing a vanilla file. Not only is it a terrible idea, but Minecraft reserves these, and it won&#39;t even work.</p><h2 id="where-to-use-namespaces" tabindex="-1">Where to use namespaces? <a class="header-anchor" href="#where-to-use-namespaces" aria-label="Permalink to &quot;Where to use namespaces?&quot;">​</a></h2><p>In short, you should use namespaces as often as you can.</p><p>For starters, you should use a namespace when adding custom entities to the game.</p><p><code class="shiki"><span>sirlich:shark</span></code> is much better than <code class="shiki"><span>shark</span></code>.</p><p>It would be best if you also used namespaces for components and events. Just like Mojang uses <code class="shiki"><span>minecraft:pig_saddled</span></code> you should use <code class="shiki"><span>namespace:my_mob_event</span></code>, and <code class="shiki"><span>namespace:my_component_group</span></code>.</p><p>It would be best if you also used namespaces in animation controllers, render controllers, and animations.</p><p>For example: <code class="shiki"><span>controller.animation.namespace.entity_name.action</span></code> is better than <code class="shiki"><span>controller.animation.my_action</span></code>.</p><h2 id="where-not-to-use-namespaces" tabindex="-1">Where NOT to use namespaces. <a class="header-anchor" href="#where-not-to-use-namespaces" aria-label="Permalink to &quot;Where NOT to use namespaces.&quot;">​</a></h2><p>The actual file structure does not need namespaces.</p><p><code class="shiki"><span>animations/namespace/my_entity/animation</span></code> is more confusing than <code class="shiki"><span>animations/my_entity/animation</span></code>.</p><ul><li><strong>Note:</strong> The following folders are exceptions: <code class="shiki"><span>functions</span></code>, <code class="shiki"><span>structures</span></code>, <code class="shiki"><span>loot_tables</span></code>, <code class="shiki"><span>trade_tables</span></code>, <code class="shiki"><span>sounds</span></code>, and <code class="shiki"><span>textures</span></code>. <ul><li>Using a <strong>namespace</strong> in these folders is recommended to prevent conflicts with other packs.</li><li><strong>Example:</strong> <code class="shiki"><span>BP/functions/namespace/test.mcfunction</span></code></li></ul></li></ul>',22)]))}const u=s(c,[["render",i]]);export{h as __pageData,u as default};
